<template><el-card shadow="never"><el-alert title="按商品和仓库计算移动加权平均成本，保留6位小数。历史成本未知时不输出零成本毛利。期初成本只能由管理员登记，登记后不能用此入口覆盖。" type="info" :closable="false" /><div style="display:flex;gap:12px;margin:16px 0"><el-checkbox v-model="unknownOnly">仅成本未初始化</el-checkbox><el-button @click="load">刷新</el-button></div><el-table :data="filtered" border v-loading="loading"><el-table-column label="商品" min-width="150"><template #default="{row}">{{products[row.product_id]||row.product_id}}</template></el-table-column><el-table-column label="仓库" min-width="120"><template #default="{row}">{{warehouses[row.warehouse_id]||row.warehouse_id}}</template></el-table-column><el-table-column prop="quantity" label="数量" width="100" /><el-table-column label="库存价值" width="140"><template #default="{row}">{{row.cost_initialized?Number(row.cost_value).toFixed(6):'成本未知'}}</template></el-table-column><el-table-column label="移动平均单位成本" width="170"><template #default="{row}">{{row.cost_initialized&&row.quantity?(Number(row.cost_value)/row.quantity).toFixed(6):'—'}}</template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button v-if="user.isAdmin&&!row.cost_initialized&&row.quantity>0" size="small" @click="open(row)">登记期初成本</el-button></template></el-table-column></el-table><el-dialog v-model="visible" title="登记可核实的期初成本" width="500px"><el-form label-width="110px"><el-form-item label="库存数量">{{current?.quantity}}</el-form-item><el-form-item label="单位成本"><el-input v-model="unit" placeholder="最多6位小数" /></el-form-item><el-form-item label="资料依据"><el-input v-model="reason" type="textarea" maxlength="200" /></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">确认登记</el-button></template></el-dialog></el-card></template>
<script setup lang="ts">
import { newRequestId } from '@/utils/requestId'
import {ref,computed,onMounted} from 'vue'
import {get,post} from '@/utils/request'
import {useUserStore} from '@/stores/user'
import {ElMessage} from 'element-plus'
const user=useUserStore()
const rows=ref<any[]>([]),products=ref<Record<number,string>>({}),warehouses=ref<Record<number,string>>({}),loading=ref(false),saving=ref(false),unknownOnly=ref(false),visible=ref(false),current=ref<any>(),unit=ref(''),reason=ref(''),key=ref('')
const filtered=computed(()=>rows.value.filter(x=>!unknownOnly.value||!x.cost_initialized))
async function load(){loading.value=true;try{const [i,p,w]=await Promise.all([get<any[]>('/inventory'),get<any[]>('/products'),get<any[]>('/warehouses')]);rows.value=i.data||[];products.value=Object.fromEntries((p.data||[]).map(x=>[x.id,x.name]));warehouses.value=Object.fromEntries((w.data||[]).map(x=>[x.id,x.name]))}catch{}finally{loading.value=false}}
function open(row:any){current.value=row;unit.value='';reason.value='';key.value=newRequestId();visible.value=true}
async function save(){if(!unit.value||!reason.value.trim()){ElMessage.warning('请填写成本与资料依据');return}saving.value=true;try{await post('/inventory/cost/opening',{inventory_id:current.value.id,book_qty:current.value.quantity,unit_cost:unit.value,reason:reason.value,request_id:key.value});visible.value=false;await load();ElMessage.success('已登记期初成本')}catch{}finally{saving.value=false}}
onMounted(load)
</script>
